{
  "outcome": "deny",
  "rationale": "We must deny this claim because the automated findings and the claimant's account confirm that the vehicle was being used for a commercial rideshare trip during the incident. This situation is explicitly excluded under Section 4, Commercial and Rideshare Use, which states that coverage does not apply while carrying persons for a fee.",
  "citations": [
    {
      "clause_id": "PLUS-4.4",
      "quote": "We do not cover loss that occurs while the covered vehicle is being used to carry persons or property for a fee, including rideshare, taxi, courier and paid delivery services"
    }
  ]
}
